t = int(input())

def solve():
	N = int(input())
	A = [int(x) for x in input().split(' ')]
	S = input().strip('\n')
	sA = list(sorted(A))
	if sA == A:
		print('0')
		return
	(firsts, firstn, lasts, lastn, firstw, lastw) = [-1] * 6
	for i in range(N):
		if S[i] == 'S':
			if firsts == -1:
				firsts = i
			lasts = i
		else:
			if firstn == -1:
				firstn = i
			lastn = i
		if sA[i] != A[i]:
			if firstw == -1:
				firstw = i
			lastw = i
	if (firsts >= 0 and firstn >= 0) and (firstw >= firsts and lastw <= lastn or (firstw >= firstn and lastw <= lasts)):
		print('1')
	elif firsts >= 0 and firstn >= 0:
		print('2')
	else:
		print('-1')
while t:
	solve()
	t -= 1
